            case '/archive':$id=$this->id();if($id===''){if($this->api){throw new Problem('INVALID_INPUT','شناسه رزرو لازم است.');}$this->page('آرشیو دارای مجوز','product-archive-lookup',[],$error);break;}$this->page('آرشیو تحت مجوز','product-session',['booking'=>['id'=>$id],'rows'=>$this->consult->archive($a,$id,(int)($_GET['after']??0)),'files'=>(new PrivateFiles($this->db,new Audit($this->db)))->listing($a,$id)],$error);break;
            case '/organizations':$this->page('سازمان‌ها و عضویت پایه','product-organizations',['rows'=>$this->db->all('SELECT o.*,(SELECT COUNT(*) FROM m_memberships m WHERE m.org_id=o.id) AS member_count FROM m_organizations o ORDER BY name'.$this->window()),'members'=>$this->db->all('SELECT m.org_id,m.user_id,u.display_name FROM m_memberships m JOIN m_users u ON u.id=m.user_id ORDER BY m.org_id LIMIT 200')],$error);break;
            case '/general':$this->page('تنظیمات عمومی','product-general',['settings'=>Branding::settings($this->db)],$error);break;
            case '/notification-templates':$this->page('قالب‌های اعلان','product-notifications',['mode'=>'templates','rows'=>$this->db->all('SELECT * FROM m_notification_templates ORDER BY created_at DESC'.$this->window())],$error);break;
            case '/notification-deliveries':$this->page('سوابق اعلان','product-notifications',['mode'=>'deliveries','rows'=>$this->db->all('SELECT * FROM m_notification_deliveries ORDER BY created_at DESC'.$this->window())],$error);break;
            case '/reports':$stats=[];foreach(['mentors'=>"SELECT COUNT(*) FROM m_mentors WHERE status='active'",'published_experiences'=>'SELECT COUNT(*) FROM m_experiences WHERE public_version_id IS NOT NULL','open_tickets'=>"SELECT COUNT(*) FROM m_tickets WHERE state='open'",'completed_sessions'=>"SELECT COUNT(*) FROM m_bookings WHERE state='completed'"] as $key=>$sql){$stats[$key]=(int)$this->db->run($sql)->fetchColumn();}$this->page('گزارش عملیاتی','product-reports',['stats'=>$stats,'feedback'=>$this->db->all('SELECT f.*,u.display_name FROM m_feedback f JOIN m_users u ON u.id=f.user_id ORDER BY f.created_at DESC'.$this->window()),'states'=>$this->db->all('SELECT state,COUNT(*) AS total FROM m_bookings GROUP BY state')],$error);break;
        }return true;
    }
    private function bookingPage(array $b,bool $admin,?string $error):void
    {$this->page('جزئیات درخواست مشاوره','product-booking',['booking'=>$b,'admin'=>$admin,'events'=>$this->db->all('SELECT event,note,created_at FROM m_booking_events WHERE booking_id=? ORDER BY id',[$b['id']]),'proposals'=>$this->db->all('SELECT * FROM m_time_proposals WHERE booking_id=? ORDER BY created_at DESC',[$b['id']])],$error);}
    private function ticketPage(array $a,string $id,bool $admin,?string $error):void
    {$t=$this->ops->getTicket($a,$id);$this->page('پرونده پشتیبانی','product-ticket',['ticket'=>$t,'admin'=>$admin,'rows'=>$this->db->all('SELECT m.*,u.display_name FROM m_ticket_messages m JOIN m_users u ON u.id=m.author_id WHERE m.ticket_id=? ORDER BY m.id',[$id])],$error);}
    public function post(string $path,array $d):bool
    {
        if($path==='/account/eitaa/test'&&$this->realm==='site'){$a=$this->actor();(new \Morshed\Core\RateLimiter($this->db,$this->view->config['app_key']))->hit('eitaa-self-test:'.$a['user_id'],2,600);$results=(new \Morshed\Product\EitaaDelivery($this->db,$this->view->config))->selfTest($a);if($this->api){$this->done('/account/security',['delivery'=>$results]);}else{$state=array_values($results)[0]??'unknown';$_SESSION['flash']=match($state){'sent'=>'سرویس ایتا ارسال پیام آزمایشی را پذیرفت؛ پیام‌های برنامک مرشد را در ایتا بررسی کن.','rejected'=>'ایتا ارسال را نپذیرفت؛ اجازهٔ دریافت پیام و اعتبار برنامک باید بررسی شود.',default=>'نتیجهٔ ارسال ایتا مشخص نشد؛ گزارش تحویل در مدیریت ثبت شد.'};header('Location: '.$this->view->url('/account/security'),true,303);}return true;}

        if($path==='/eitaa-delivery/test'&&$this->realm==='admin'){$a=$this->actor();(new \Morshed\Core\RateLimiter($this->db,$this->view->config['app_key']))->hit('eitaa-test:'.$a['user_id'],2,600);$results=(new \Morshed\Product\EitaaDelivery($this->db,$this->view->config))->test($a,$this->value($d,'username'));$this->done('/eitaa-delivery',['delivery'=>$results]);return true;}

        if($path==='/experience/submit'&&$this->realm==='site'){foreach(['title','summary'] as $key){if(is_string($d[$key]??null))$this->view->old[$key]=$d[$key];}$id=(new \Morshed\Product\Contributions($this->db))->submit($this->actor(),$d);$this->done('/experience/submit',['id'=>$id]);return true;}
        if($path==='/experience-leads/review'&&$this->realm==='admin'){(new \Morshed\Product\Contributions($this->db))->review($this->actor(),$d);$this->done('/experience-leads');return true;}

        if((new ClassificationsController($this->db,$this->view,$this->actor,$this->realm,$this->api))->post($path,$d)){return true;}if((new KnowledgeController($this->db,$this->view,$this->actor,$this->realm,$this->api))->post($path,$d)){return true;}
        if((new AtlasController($this->db,$this->view,$this->actor,$this->realm,$this->api))->post($path,$d)){return true;}
        if($this->realm==='site'&&$path==='/meeting/token'){$a=$this->actor();(new \Morshed\Core\RateLimiter($this->db,$this->view->config['app_key']))->hit('meeting-token:'.$a['user_id'],12,60);$result=(new \Morshed\Product\MeetingRooms($this->db,$this->view->config))->token($a,$this->value($d,'id'),$this->value($d,'method'));if(!$this->api){throw new Problem('NOT_FOUND','مسیر معتبر نیست.',404);}$this->done('/meeting?id='.$this->value($d,'id'),$result);return true;}
        if($this->realm==='site'&&$path==='/taxonomy/save'){throw new Problem('ACCESS_DENIED','مجوز مدیریت موضوعات لازم است.',403);}
        $site=['/account/avatar','/account/saved/set','/mentor/accept','/mentor/avatar','/mentor/evidence','/mentor/profile/save','/mentor/experience/save','/mentor/experience/approve','/mentor/experience/submit','/mentor/calendar/settings','/mentor/calendar/rule','/mentor/calendar/remove','/mentor/calendar/exception','/bookings/create','/booking/action','/booking/propose','/booking/answer','/session/message','/session/files','/support/create','/ticket/reply','/feedback'];
        $admin=['/mentors/invite','/mentors/status','/taxonomy/save','/experience/save','/experience/submit','/experience/review','/experience/unpublish','/storefront/save','/storefront/publish','/bookings/internal','/booking/action','/ticket/reply','/archives/grant','/archives/revoke','/organizations/save','/organizations/member','/general/save','/general/asset','/notification-templates/create','/notification-deliveries/send'];
        if(!in_array($path,$this->realm==='site'?$site:$admin,true)){return false;}
        if(($this->realm==='site'&&str_starts_with($path,'/mentor/')&&!in_array($path,['/mentor/evidence','/mentor/avatar','/mentor/calendar/settings','/mentor/calendar/rule','/mentor/calendar/remove','/mentor/calendar/exception'],true))||($this->realm==='admin'&&$path==='/mentors/invite')){throw new Problem('FLOW_RETIRED','مدیریت نقش و تجربه‌ها اکنون مستقیماً در پنل مدیریت انجام می‌شود.',410);}
        $a=$this->actor();$result=[];$back='/';$id=$this->value($d,'id');$adminRealm=$this->realm==='admin';
        foreach($d as $k=>$v){if(is_string($k)&&is_string($v)&&!str_contains($k,'password')&&!in_array($k,['csrf','token','code'],true)){$this->view->old[$k]=$v;}}
        if(isset($d['_topics_present'])||isset($d['topics'])){$this->view->old['topics']=is_array($d['topics']??null)?array_slice(array_filter($d['topics'],'is_string'),0,20):[];}
        foreach(['problems','audiences'] as $field){if(isset($d[$field])&&is_array($d[$field])){$this->view->old[$field]=$d[$field];}}
        if(isset($d['_issues_present'])||isset($d['issues'])){$this->view->old['issues']=is_array($d['issues']??null)?array_slice(array_filter($d['issues'],'is_string'),0,20):[];}
        if(is_array($d['terms']??null)){$this->view->old['terms']=array_slice(array_filter($d['terms'],'is_string'),0,20);}
        if(is_array($d['asset_ids']??null)){$this->view->old['asset_ids']=array_slice(array_filter($d['asset_ids'],'is_string'),0,5);}
        // Pick the return page before mutation, so validation errors preserve entered fields.
        $back=match(true){$path==='/account/saved/set'=>'/account/saved',$path==='/mentor/evidence'=>'/mentor/experience',str_starts_with($path,'/general/')=>'/general',str_starts_with($path,'/notification-templates/')=>'/notification-templates',str_starts_with($path,'/notification-deliveries/')=>'/notification-templates',str_starts_with($path,'/mentor/calendar')=>'/mentor/calendar',str_starts_with($path,'/mentor/experience')=>'/mentor/experience',str_starts_with($path,'/mentor/')=>'/mentor',str_starts_with($path,'/mentors/')=>'/mentors',str_starts_with($path,'/taxonomy/')=>'/taxonomy',str_starts_with($path,'/storefront/')=>'/storefront',$path==='/experience/save'=>'/experience/edit',str_starts_with($path,'/experience/')=>'/experience',str_starts_with($path,'/archives/')=>'/archives',str_starts_with($path,'/organizations/')=>'/organizations',str_starts_with($path,'/ticket/')=>'/ticket',str_starts_with($path,'/session/')=>'/session',str_starts_with($path,'/booking/')||$path==='/feedback'=>'/booking',str_starts_with($path,'/bookings/')=>$adminRealm?'/bookings':'/sessions',default=>'/support'};
        try{
            if(isset($d['starts_local'])){$d['starts_at']=Consultations::localTimestamp($this->value($d,'starts_local'));}
            switch($path){
                case '/account/saved/set':$saveKind=Policy::choice($d['kind']??'mentor',['mentor','experience']);$saved=Policy::integer($d['saved']??'',0,1)===1;$catalog=new Catalog($this->db);if($saveKind==='experience'){$catalog->saveExperience($a,$this->value($d,'experience_id'),$saved);$back='/account/saved?tab=experiences';}else{$catalog->save($a,$this->value($d,'mentor_id'),$saved);}$result=['saved'=>$saved];break;
                case '/account/avatar':$assets=new ContentAssets($this->db,new Audit($this->db));if(($d['remove']??'')==='1'){$assets->removeAvatar($a);}else{$assets->upload($a,$_FILES['attachment']??[],true,false,true);}$back='/account/profile';break;
                case '/mentor/avatar':$result=['asset_id'=>(new ContentAssets($this->db,new Audit($this->db)))->upload($a,$_FILES['attachment']??[],true)];$back='/mentor';break;
                case '/mentor/evidence':$result=['asset_id'=>(new ContentAssets($this->db,new Audit($this->db)))->upload($a,$_FILES['attachment']??[])];$back='/mentor/experience';break;
                case '/mentor/accept':$this->content->acceptInvite($a);break;
                case '/mentor/profile/save':$this->content->mentorProfile($a,$d);break;
                case '/mentor/experience/save':if(\Morshed\Core\Upgrade::ready($this->db)&&!array_key_exists('problem',$d)){throw new Problem('INVALID_INPUT','فرم ساختاریافته تجربه را تکمیل کنید.');}$result=$this->content->saveExperience($a,$d);$id=$result['experience_id'];$back='/mentor/experience';break;
                case '/mentor/experience/approve':(new ExperienceCases($this->db,new Audit($this->db)))->ownerApprove($a,$id);$back='/mentor/experiences';break;
                case '/mentor/experience/submit':$this->content->submit($a,$id);$back='/mentor/experiences';break;
                case '/mentor/calendar/settings':$this->consult->settings($a,$d);break;
                case '/mentor/calendar/rule':$this->consult->rule($a,$d);break;
                case '/mentor/calendar/remove':$this->consult->removeRule($a,$id,$this->value($d,'kind','weekly'));break;
                case '/mentor/calendar/exception':$this->consult->exception($a,$this->value($d,'date'),($d['remove']??'0')==='1');break;
                case '/bookings/create':$id=$this->consult->reserve($a,$d);$back='/booking';$result=['id'=>$id];break;
                case '/bookings/internal':$id=$this->consult->reserve($a,$d,true);$back='/booking';$result=['id'=>$id];break;
                case '/booking/action':$this->consult->transition($a,$id,$this->value($d,'action'),$this->value($d,'note'),$adminRealm);break;
                case '/booking/propose':$result=['proposal_id'=>$this->consult->propose($a,$id,Policy::integer($d['starts_at']??'',1,4102444800))];break;
                case '/booking/answer':$proposal=$this->db->one('SELECT booking_id FROM m_time_proposals WHERE id=?',[$this->value($d,'proposal_id')]);$this->consult->answerProposal($a,$this->value($d,'proposal_id'),($d['accept']??'0')==='1');$id=$proposal['booking_id'];break;
                case '/session/files':$result=['file_id'=>(new PrivateFiles($this->db,new Audit($this->db)))->upload($a,$id,$_FILES['attachment']??[])];break;
                case '/general/asset':$kind=$this->value($d,'kind');Policy::choice($kind,['footer_logo','enamad']);$asset=($d['remove']??'')==='1'?'':(new ContentAssets($this->db,new Audit($this->db)))->upload($a,$_FILES['attachment']??[],false,true);Branding::asset($this->db,new Audit($this->db),$a,$kind,$asset);$result=['asset_id'=>$asset];break;
                case '/general/save':(new Delivery($this->db,new Audit($this->db)))->settings($a,$d);break;
                case '/notification-templates/create':$result=['id'=>(new Delivery($this->db,new Audit($this->db)))->template($a,$d)];break;
                case '/notification-deliveries/send':$result=['notification_id'=>(new Delivery($this->db,new Audit($this->db)))->send($a,$d)];break;
                case '/session/message':$result=$this->consult->message($a,$id,$this->value($d,'client_key'),$this->value($d,'body'));break;
                case '/support/create':$id=$this->ops->ticket($a,$d);$back='/ticket';$result=['id'=>$id];break;
                case '/ticket/reply':$this->ops->reply($a,$id,$this->value($d,'body'),$adminRealm?$this->value($d,'state','open'):null);break;
                case '/feedback':$this->ops->feedback($a,$id,Policy::integer($d['score']??'',1,5),$this->value($d,'body'));break;
                case '/mentors/invite':$id=$this->content->invite($a,$d);break;
                case '/mentors/status':$this->content->mentorState($a,$id,$this->value($d,'status'));break;
                case '/taxonomy/save':if(isset($d['related_topics_present'])){$d['related_topics']=$d['related_topics']??[];}if(($_FILES['attachment']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$d['icon_asset_id']=(new ContentAssets($this->db,new Audit($this->db)))->upload($a,$_FILES['attachment'],false,false,false,true);}elseif(($d['remove_icon']??'')==='1'){$d['icon_asset_id']=null;}$id=$this->content->term($a,$d);$_GET['kind']=$d['kind'];$result=['id'=>$id];break;
                case '/experience/save':$result=(new ExperienceCases($this->db,new Audit($this->db)))->save($a,$d);$id=$result['experience_id'];$back='/experience/edit';break;
                case '/experience/submit':(new ExperienceCases($this->db,new Audit($this->db)))->submit($a,$id);$back='/experiences';break;
                case '/experience/review':$this->content->review($a,$id,$this->value($d,'decision'),$this->value($d,'note'));break;
                case '/experience/unpublish':$this->content->unpublish($a,$id);$back='/experiences';break;
                case '/storefront/save':$this->view->old['blocks_json']=$this->value($d,'blocks_json');try{$blocks=json_decode($this->value($d,'blocks_json'),true,16,JSON_THROW_ON_ERROR);}catch(\JsonException $e){throw new Problem('INVALID_JSON','ساختار بلوک‌های ویترین معتبر نیست.');}if(!is_array($blocks)||!array_is_list($blocks)){throw new Problem('INVALID_INPUT','فهرست بلوک‌ها لازم است.');}$id=$this->content->saveStore($a,$blocks);$result=['id'=>$id];$back='/storefront?draft='.$id;break;
                case '/storefront/publish':$this->content->publishStore($a,$id);break;
                case '/archives/grant':$id=$this->ops->grant($a,$d);$result=['id'=>$id];break;
                case '/archives/revoke':$this->ops->revokeGrant($a,$id);break;
                case '/organizations/save':$id=$this->ops->organization($a,$d);break;
                case '/organizations/member':$this->ops->membership($a,$this->value($d,'org_id'),$this->value($d,'user_id'),($d['remove']??'0')==='1');break;
            }
        }catch(\PDOException $e){$failure=new Problem('STORAGE_UNAVAILABLE','ذخیره انجام نشد. داده‌های فرم حفظ شده‌اند؛ پس از بررسی ارتباط دوباره تلاش کنید.',503);if($this->api||$path==='/account/avatar'){throw $failure;}http_response_code(503);$_GET['id']=$id?:($d['experience_id']??'');$this->get($back,$failure->getMessage());return true;}catch(Problem $e){if($this->api||$path==='/account/avatar'){throw $e;}http_response_code($e->status);$_GET['id']=$id?:($d['experience_id']??'');$this->get($back,$e->getMessage());return true;}
        $event=match($path){'/bookings/create','/bookings/internal'=>'CONSULTATION_REQUESTED','/booking/action'=>match($d['action']??''){'accept'=>'CONSULTATION_CONFIRMED','cancel'=>'SESSION_CANCELLED','complete'=>'SESSION_COMPLETED',default=>null},'/feedback'=>'FEEDBACK_SUBMITTED',default=>null};
        if($event&&$id!==''){(new \Morshed\Product\InteractionEvents($this->db))->record($a,$event,$event==='FEEDBACK_SUBMITTED'?'SESSION':'CONSULTATION_REQUEST',$id,$event==='FEEDBACK_SUBMITTED'?['score'=>(int)($d['score']??0)]:[],($d['idempotency_key']??$event).'|'.$id);}
        if($path==='/taxonomy/save'){$back.='?kind='.rawurlencode($d['kind']);}
        $this->done($back.($id&&in_array($back,['/experience/edit','/mentor/experience','/booking','/ticket','/session','/experience'],true)?'?id='.rawurlencode($id):''),$result);return true;
    }
